package com.simibubi.create.test;

import com.simibubi.create.*;
import com.simibubi.create.api.behaviour.display.DisplaySource;
import com.simibubi.create.api.stress.BlockStressValues;
import com.simibubi.create.content.kinetics.base.*;
import com.simibubi.create.content.kinetics.clock.*;
import com.simibubi.create.content.kinetics.motor.CreativeMotorBlock;
import com.simibubi.create.content.redstone.displayLink.*;
import com.simibubi.create.content.redstone.displayLink.target.DisplayTargetStats;
import com.simibubi.create.content.trains.display.*;
import java.util.*;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.item.*;
import net.minecraft.world.item.crafting.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.phys.Vec3;

/** Proposed genuine clock network, native world clock, real display delivery and source-surprise regressions. UNRUN. */
public final class CuckooClockGameTests {
 private static final BlockPos C=new BlockPos(4,5,4),M=C.north(),L=C.above(2),T=L.east(3);
 private static CuckooClockBlockEntity clock(GameTestHelper h){return h.getBlockEntity(C,CuckooClockBlockEntity.class);}
 private static KineticBlockEntity motor(GameTestHelper h){return h.getBlockEntity(M,KineticBlockEntity.class);}
 private static void setup(GameTestHelper h,boolean mysterious){h.setBlock(C,mysterious?AllBlocks.MYSTERIOUS_CUCKOO_CLOCK:AllBlocks.CUCKOO_CLOCK);h.setBlock(C,h.getBlockState(C).setValue(CuckooClockBlock.HORIZONTAL_FACING,Direction.SOUTH));h.setBlock(M,AllBlocks.CREATIVE_MOTOR.defaultBlockState().setValue(CreativeMotorBlock.FACING,Direction.SOUTH));motor(h).setGeneratedSpeed(64);}
 private static void tick(GameTestHelper h){CuckooClockBlockEntity.tick(h.getLevel(),h.absolutePos(C),h.getBlockState(C),clock(h));}
 /** Actual native time command, restored synchronously before another server callback can run. */
 private static void atTime(GameTestHelper h,int time,Runnable operation){var server=h.getLevel().getServer();long previous=h.getLevel().getOverworldClockTime();h.assertTrue(previous>=0&&previous<=Integer.MAX_VALUE,"Native original shared time fits actual time command restoration");var source=server.createCommandSourceStack().withSuppressedOutput();try{server.getCommands().performPrefixedCommand(source,"time set "+time);operation.run();}finally{server.getCommands().performPrefixedCommand(source,"time set "+previous);}}
 private static void connectClock(GameTestHelper h){h.setBlock(C.above(),Blocks.AIR);h.setBlock(L,Blocks.AIR);h.setBlock(C.above(),AllBlocks.DISPLAY_LINK.defaultBlockState().setValue(DisplayLinkBlock.FACING,Direction.UP));h.setBlock(T.below(),Blocks.STONE);h.setBlock(T,Blocks.OAK_SIGN);h.getBlockEntity(C.above(),DisplayLinkBlockEntity.class).target(h.absolutePos(T));}
 private static DisplayLinkBlockEntity actualLink(GameTestHelper h){return h.getBlockEntity(C.above(),DisplayLinkBlockEntity.class);}
 private static CompoundTag config(DisplaySource source){var config=new CompoundTag();config.putString("Id",source.getId().toString());return config;}
 private static String sign(GameTestHelper h){return h.getBlockEntity(T,SignBlockEntity.class).getText(net.minecraft.world.level.block.entity.SignTextSlot.FRONT).getMessages(false).getFirst().getString();}
 private static DisplayLinkContext context(GameTestHelper h){return new DisplayLinkContext(h.getLevel(),actualLink(h));}
 @GameTest public void originalFourAxesRearOnlyShaftShapeAndStressUseRealRegisteredBlocks(GameTestHelper h){for(var block:List.of(AllBlocks.CUCKOO_CLOCK,AllBlocks.MYSTERIOUS_CUCKOO_CLOCK))for(var face:Direction.Plane.HORIZONTAL){var state=block.defaultBlockState().setValue(CuckooClockBlock.HORIZONTAL_FACING,face);h.assertValueEqual(block.getRotationAxis(state),face.getAxis(),"Original clock rotation axis");for(var side:Direction.values())h.assertTrue(block.hasShaftTowards(h.getLevel(),h.absolutePos(C),state,side)==(side==face.getOpposite()),"Only actual rear shaft face");h.assertTrue(state.getShape(h.getLevel(),h.absolutePos(C)).bounds().maxY==19/16d&&BlockStressValues.getImpact(block)==1,"Original19-high shape and stress1");}h.succeed();}
 @GameTest(maxTicks=40)public void actualNativeNoonWindowStartsPigOnceAndTransientPacketDoesNotBecomeSavedAnimation(GameTestHelper h){setup(h,false);h.runAfterDelay(12,()->{h.assertTrue(clock(h).getSpeed()!=0,"Real native motor powers actual clock");atTime(h,5950,()->{tick(h);h.assertValueEqual(clock(h).animationType,CuckooClockBlockEntity.Animation.NONE,"Before noon no source announcement");});atTime(h,6000,()->tick(h));h.assertValueEqual(clock(h).animationType,CuckooClockBlockEntity.Animation.PIG,"Actual shared noon starts genuine pig animation");var packet=clock(h).getUpdateTag(h.getLevel().registryAccess());h.assertValueEqual(packet.getStringOr("Animation",""),"PIG","Native packet carries source transient animation");h.assertFalse(clock(h).getUpdateTag(h.getLevel().registryAccess()).contains("Animation"),"Pending update consumed exactly once");h.assertFalse(clock(h).saveWithFullMetadata(h.getLevel().registryAccess()).contains("Animation"),"Original animation never becomes persistent stock/state");h.succeed();});}
 @GameTest(maxTicks=40)public void actualBedtimeRequiresOriginalNarrowMinuteWindow(GameTestHelper h){setup(h,false);h.runAfterDelay(12,()->{atTime(h,12500,()->tick(h));h.assertValueEqual(clock(h).animationType,CuckooClockBlockEntity.Animation.NONE,"Minute30 lies before source bedtime announcement");atTime(h,12550,()->tick(h));h.assertValueEqual(clock(h).animationType,CuckooClockBlockEntity.Animation.CREEPER,"Actual18:33 lies inside source32..35-minute window");h.succeed();});}
 @GameTest(maxTicks=90)public void realMotorZeroPausesAndRealReverseRpmResumesTheSameAnnouncement(GameTestHelper h){setup(h,false);h.runAfterDelay(12,()->{atTime(h,6000,()->tick(h));motor(h).setGeneratedSpeed(0);});var saved=new float[1];h.runAfterDelay(20,()->{h.assertTrue(clock(h).getSpeed()==0,"Real network stopped");saved[0]=clock(h).animationProgress.getValue();});h.runAfterDelay(36,()->{h.assertTrue(clock(h).animationProgress.getValue()==saved[0]&&clock(h).animationType==CuckooClockBlockEntity.Animation.PIG,"Original announcement progress paused without replacement");motor(h).setGeneratedSpeed(-64);});h.runAfterDelay(50,()->{h.assertTrue(clock(h).getSpeed()!=0&&clock(h).animationProgress.getValue()>saved[0]&&clock(h).animationType==CuckooClockBlockEntity.Animation.PIG,"Real reversed motor resumes same genuine source animation");h.succeed();});}
 @GameTest(maxTicks=100)public void genuineMysteriousNoonExplosionConsumesItsRealClockInsteadOfReturningAFreeItem(GameTestHelper h){setup(h,true);h.runAfterDelay(12,()->{atTime(h,6000,()->tick(h));h.assertValueEqual(clock(h).animationType,CuckooClockBlockEntity.Animation.SURPRISE,"Actual mysterious variant transforms noon pig announcement into genuine surprise");});h.runAfterDelay(72,()->{h.assertFalse(h.getBlockState(C).getBlock() instanceof CuckooClockBlock,"Original real surprise destroyed its source at animation50");h.assertTrue(h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(h.absolutePos(C)).inflate(5),item->item.getItem().is(AllBlocks.MYSTERIOUS_CUCKOO_CLOCK.asItem())).isEmpty(),"Source destroyBlock(false) cannot refund a second original clock");h.succeed();});}
 @GameTest(maxTicks=35)public void actualTimeSourceWritesSourceFiveMinuteRounded24HourLabelToRealNativeSign(GameTestHelper h){setup(h,false);connectClock(h);h.runAfterDelay(12,()->{var data=config(AllDisplaySources.TIME_OF_DAY);data.putInt("Cycle",1);data.putString("Label","Clock");atTime(h,6130,()->{h.assertTrue(actualLink(h).configure(data,0),"Genuine clock source and existing native editor configure");h.assertValueEqual(sign(h),"Clock 12:05","Source five-minute rounding delivered to actual sign");});h.succeed();});}
 @GameTest(maxTicks=35)public void actualTwelveHourSourceUsesNativeTranslatedAmPmComponentAndMidnightTwelve(GameTestHelper h){setup(h,false);connectClock(h);h.runAfterDelay(12,()->{atTime(h,18000,()->{h.assertTrue(actualLink(h).configure(config(AllDisplaySources.TIME_OF_DAY),0),"Source default12-hour native configuration");var text=AllDisplaySources.TIME_OF_DAY.provideText(context(h),new DisplayTargetStats(4,32,AllDisplayTargets.SIGN)).getFirst();h.assertTrue(text.getString().startsWith("12:00 ")&&text.getSiblings().contains(net.minecraft.network.chat.Component.translatable("create.generic.daytime.am")),"Original midnight12 and genuine create generic am translation component");});h.succeed();});}
 @GameTest(maxTicks=75)public void actualStopwatchRefreshesByTwentyTicksAndNativePowerFallingEdgeResetsStart(GameTestHelper h){setup(h,false);connectClock(h);h.runAfterDelay(12,()->{h.assertTrue(actualLink(h).configure(config(AllDisplaySources.STOPWATCH),0),"Actual original stopwatch configured");h.assertValueEqual(sign(h)," 0:00","Genuine game-time start");});var previous=new long[1];h.runAfterDelay(36,()->{h.assertValueEqual(sign(h)," 0:01","Source20-tick passive refresh reaches real sign");previous[0]=actualLink(h).getSourceConfig().getLongOr("StartTime",-1);h.setBlock(C.above().west(),Blocks.REDSTONE_BLOCK);});h.runAfterDelay(43,()->h.setBlock(C.above().west(),Blocks.AIR));h.runAfterDelay(48,()->{h.assertTrue(actualLink(h).getSourceConfig().getLongOr("StartTime",-1)>previous[0]&&sign(h).equals(" 0:00"),"Actual native powered→unpowered transition resets source StartTime and delivers once");h.succeed();});}
 @GameTest(maxTicks=40)public void stoppedGenuineClockWritesDashPlaceholderAndRetainsStopwatchStartAcrossNativeSave(GameTestHelper h){setup(h,false);connectClock(h);h.runAfterDelay(12,()->{h.assertTrue(actualLink(h).configure(config(AllDisplaySources.STOPWATCH),0),"Actual original stopwatch");motor(h).setGeneratedSpeed(0);});h.runAfterDelay(25,()->{actualLink(h).updateGatheredData();h.assertValueEqual(sign(h),"--:--","Source stopped clock placeholder");var data=actualLink(h).saveWithFullMetadata(h.getLevel().registryAccess());var fresh=(DisplayLinkBlockEntity)BlockEntity.loadStatic(h.absolutePos(C.above()),h.getBlockState(C.above()),data,h.getLevel().registryAccess());h.assertTrue(fresh!=null&&fresh.getLevel()==null&&fresh.activeSource==AllDisplaySources.STOPWATCH&&fresh.getSourceConfig().getLongOr("StartTime",-1)==actualLink(h).getSourceConfig().getLongOr("StartTime",-2),"Actual source runtime elapsed origin survives native pre-level decode");h.succeed();});}
 @GameTest(maxTicks=35)public void clockSourceSchemaClampsCyclePreservesRuntimeAndOriginalRefreshAndAliases(GameTestHelper h){setup(h,false);connectClock(h);h.runAfterDelay(12,()->{var data=config(AllDisplaySources.TIME_OF_DAY);data.putInt("Cycle",Integer.MAX_VALUE);h.assertTrue(actualLink(h).configure(data,0)&&actualLink(h).getSourceConfig().getIntOr("Cycle",-1)==1,"Actual native source editor clamps two legitimate time-cycle choices");actualLink(h).getSourceConfig().putLong("StartTime",456);data.putInt("Cycle",0);h.assertTrue(actualLink(h).configure(data,0)&&actualLink(h).getSourceConfig().getLongOr("StartTime",0)==456,"Bounded editor preserves runtime-only actual source metadata");h.assertTrue(AllDisplaySources.STOPWATCH.getPassiveRefreshTicks()==20&&DisplaySource.get(net.minecraft.resources.Identifier.parse("create:cuckoo_clock_source_stop_watch"))==AllDisplaySources.STOPWATCH,"Original interval and legacy source alias");h.succeed();});}
 @GameTest(maxTicks=40)public void actualPoweredBoardReceivesOriginalInstantClockLayoutAndFiveMinuteText(GameTestHelper h){setup(h,false);connectClock(h);for(int x=0;x<2;x++)h.setBlock(T.east(x),AllBlocks.DISPLAY_BOARD.defaultBlockState().setValue(FlapDisplayBlock.HORIZONTAL_FACING,Direction.SOUTH));h.setBlock(T.west(),AllBlocks.COGWHEEL.defaultBlockState().setValue(com.simibubi.create.content.kinetics.simpleRelays.ShaftBlock.AXIS,Direction.Axis.Z));h.setBlock(T.west().north(),AllBlocks.CREATIVE_MOTOR.defaultBlockState().setValue(CreativeMotorBlock.FACING,Direction.SOUTH));h.getBlockEntity(T.west().north(),KineticBlockEntity.class).setGeneratedSpeed(64);h.runAfterDelay(15,()->{var data=config(AllDisplaySources.TIME_OF_DAY);data.putInt("Cycle",1);atTime(h,6130,()->h.assertTrue(actualLink(h).configure(data,0),"Real clock and actual powered board configure"));var board=h.getBlockEntity(T,FlapDisplayBlockEntity.class);var layout=board.getLines().getFirst();h.assertTrue(board.isController&&board.isRunning&&layout.isLayout("Instant")&&layout.getSections().size()==1&&layout.getSections().getFirst().getText().getString().equals("12:05"),"Source Instant layout and exact rounded time reach original native kinetic board");h.succeed();});}
 @GameTest public void mysteriousVariantDoesNotAdvertiseInventedRegularClockDisplaySources(GameTestHelper h){setup(h,true);connectClock(h);var sources=DisplaySource.getAll(h.getLevel(),h.absolutePos(C));h.assertFalse(sources.contains(AllDisplaySources.TIME_OF_DAY)||sources.contains(AllDisplaySources.STOPWATCH),"Only original regular Cuckoo Clock carries time/stopwatch source registrations");h.succeed();}
 @GameTest public void actualClockCraftingAndNativeLootRetainOriginalFiniteInputs(GameTestHelper h){var input=CraftingInput.of(1,3,List.of(new ItemStack(Items.OAK_PLANKS),new ItemStack(AllBlocks.ANDESITE_CASING),new ItemStack(Items.CLOCK)));var result=h.getLevel().getServer().getRecipeManager().getRecipeFor(RecipeType.CRAFTING,input,h.getLevel()).orElseThrow().value().assemble(input);h.assertTrue(result.is(AllBlocks.CUCKOO_CLOCK.asItem())&&result.getCount()==1,"Original planks/casing/clock recipe output");setup(h,false);var drops=Block.getDrops(h.getBlockState(C),h.getLevel(),h.absolutePos(C),clock(h));h.assertTrue(drops.size()==1&&drops.getFirst().is(AllBlocks.CUCKOO_CLOCK.asItem()),"Actual source loot returns precisely the one genuine clock");h.succeed();}
}
